    { size_t j; for (j = 0; j < 2; j++) { out[n++] = &s->f_r0.w[j]; } }
    { size_t j; for (j = 0; j < 2; j++) { out[n++] = &s->f_r1.w[j]; } }
    out[n++] = &s->f_y;
    out[n++] = &s->f_y0;
    out[n++] = &s->f_y1;
